// CPU halves of the vendor code: FSR 1's constant setup, NIS's config and
// filter coefficients.
#define A_CPU 1
#include "fsr1/ffx_a.h"
#include "fsr1/ffx_fsr1.h"
#include "nis/NIS_Config.h"

namespace
{
    std::string join(const char *const *pieces)
    {
        std::string text;
        for (; *pieces; ++pieces)
            text += *pieces;
        return text;
    }

    void replaceAll(std::string &text, const std::string &from, const std::string &to)
    {
        for (size_t at = text.find(from); at != std::string::npos; at = text.find(from, at + to.size()))
            text.replace(at, from.size(), to);
    }

    // raylib's attribute and uniform names, GLSL 4.30 like the passes.
    const char *const kVertex = R"GLSL(#version 430
in vec3 vertexPosition;
in vec2 vertexTexCoord;
in vec4 vertexColor;
uniform mat4 mvp;
out vec2 fragTexCoord;
out vec4 fragColor;
void main()
{
    fragTexCoord = vertexTexCoord;
    fragColor = vertexColor;
    gl_Position = mvp * vec4(vertexPosition, 1.0);
}
)GLSL";

    // Every pass works in texel rows counted from the picture's top (row 0 =
    // top, as the frame texture is uploaded); gl_FragCoord in a render target
    // is that same row, so no pass flips.
    std::string fsrPass(const char *defines, const char *glue, const char *main)
    {
        return std::string("#version 430\n#define A_GPU 1\n#define A_GLSL 1\n") + defines +
               "\n/* AMD FidelityFX Super Resolution 1 (ps2xRuntime/third_party/fsr1):\n" + join(kFsrLicenseText) + "\n*/\n" +
               join(kFfxAText) + "\nuniform sampler2D texture0;\nout vec4 finalColor;\n" + glue + "\n" + join(kFfxFsr1Text) + "\n" + main;
    }

    const char *const kEasuGlue = R"GLSL(
uniform uvec4 con0;
uniform uvec4 con1;
uniform uvec4 con2;
uniform uvec4 con3;
AF4 FsrEasuRF(AF2 p) { return textureGather(texture0, p, 0); }
AF4 FsrEasuGF(AF2 p) { return textureGather(texture0, p, 1); }
AF4 FsrEasuBF(AF2 p) { return textureGather(texture0, p, 2); }
)GLSL";
    const char *const kEasuMain = R"GLSL(
void main()
{
    AF3 c;
    FsrEasuF(c, AU2(gl_FragCoord.xy), con0, con1, con2, con3);
    finalColor = vec4(c, 1.0);
}
)GLSL";
    const char *const kRcasGlue = R"GLSL(
uniform uvec4 con;
AF4 FsrRcasLoadF(ASU2 p) { return texelFetch(texture0, clamp(p, ivec2(0), textureSize(texture0, 0) - 1), 0); }
void FsrRcasInputF(inout AF1 r, inout AF1 g, inout AF1 b) {}
)GLSL";
    const char *const kRcasMain = R"GLSL(
void main()
{
    AF3 c;
    FsrRcasF(c.r, c.g, c.b, AU2(gl_FragCoord.xy), con);
    finalColor = vec4(c, 1.0);
}
)GLSL";

    // Plain bilinear resize, for pictures larger than the window (FSR's EASU
    // and NIS's scaler only enlarge; their sharpening then runs at window size).
    const char *const kResample = R"GLSL(#version 430
uniform sampler2D texture0;
uniform vec2 srcScale; // used part of the texture (width, height fractions)
uniform vec2 outSize;
out vec4 finalColor;
void main()
{
    finalColor = vec4(textureLod(texture0, gl_FragCoord.xy / outSize * srcScale, 0.0).rgb, 1.0);
}
)GLSL";

    // NIS_Main.glsl for OpenGL: its constant buffer as a std140 block,
    // combined samplers (the header's Vulkan-style sampler2D(texture, sampler)
    // constructions are rewritten), fixed bindings.
    std::string nisSource(bool scaler, int blockHeight, int groupSize)
    {
        std::string header = join(kNisScalerText);
        replaceAll(header, "sampler2D(x, samplerLinearClamp)", "x");
        replaceAll(header, "sampler2D(x, sampler)", "x");
        return "#version 430\n#define NIS_GLSL 1\n#define NIS_USE_HALF_PRECISION 0\n#define NIS_SCALER " + std::to_string(scaler ? 1 : 0) +
               "\n#define NIS_BLOCK_WIDTH 32\n#define NIS_BLOCK_HEIGHT " + std::to_string(blockHeight) +
               "\n#define NIS_THREAD_GROUP_SIZE " + std::to_string(groupSize) + R"GLSL(
layout(std140, binding = 0) uniform const_buffer
{
    float kDetectRatio;
    float kDetectThres;
    float kMinContrastRatio;
    float kRatioNorm;
    float kContrastBoost;
    float kEps;
    float kSharpStartY;
    float kSharpScaleY;
    float kSharpStrengthMin;
    float kSharpStrengthScale;
    float kSharpLimitMin;
    float kSharpLimitScale;
    float kScaleX;
    float kScaleY;
    float kDstNormX;
    float kDstNormY;
    float kSrcNormX;
    float kSrcNormY;
    uint kInputViewportOriginX;
    uint kInputViewportOriginY;
    uint kInputViewportWidth;
    uint kInputViewportHeight;
    uint kOutputViewportOriginX;
    uint kOutputViewportOriginY;
    uint kOutputViewportWidth;
    uint kOutputViewportHeight;
    float reserved0;
    float reserved1;
};
layout(binding = 0) uniform sampler2D in_texture;
layout(binding = 1) uniform sampler2D coef_scaler;
layout(binding = 2) uniform sampler2D coef_usm;
layout(rgba8, binding = 0) uniform writeonly image2D out_texture;
)GLSL" + header + R"GLSL(
layout(local_size_x = NIS_THREAD_GROUP_SIZE) in;
void main()
{
#if NIS_SCALER
    NVScaler(gl_WorkGroupID.xy, gl_LocalInvocationID.x);
#else
    NVSharpen(gl_WorkGroupID.xy, gl_LocalInvocationID.x);
#endif
}
)GLSL";
    }

    GLuint compile(GLenum stage, const std::string &source, std::string &error)
    {
        const GLuint shader = glCreateShader(stage);
        const char *text = source.c_str();
        glShaderSource(shader, 1, &text, nullptr);
        glCompileShader(shader);
        GLint ok = 0;
        glGetShaderiv(shader, GL_COMPILE_STATUS, &ok);
        if (!ok)
        {
            GLint length = 0;
            glGetShaderiv(shader, GL_INFO_LOG_LENGTH, &length);
            std::string log(static_cast<size_t>(std::max(length, 1)), '\0');
            glGetShaderInfoLog(shader, length, nullptr, log.data());
            error = log.c_str();
            glDeleteShader(shader);
            return 0;
        }
        return shader;
    }

    GLuint computeProgram(const std::string &source, std::string &error)
    {
        const GLuint shader = compile(GL_COMPUTE_SHADER, source, error);
        if (!shader)
            return 0;
        const GLuint program = glCreateProgram();
        glAttachShader(program, shader);
        glLinkProgram(program);
        glDeleteShader(shader);
        GLint ok = 0;
        glGetProgramiv(program, GL_LINK_STATUS, &ok);
        if (!ok)
        {
            char log[2048]{};
            glGetProgramInfoLog(program, sizeof(log), nullptr, log);
            error = log;
            glDeleteProgram(program);
            return 0;
        }
        return program;
    }

    // raylib reports shader errors only to its log and falls back to its
    // default shader: compile once more here for the message.
    bool loadPass(Shader &shader, const std::string &fragment, const char *name, std::string &error)
    {
        shader = LoadShaderFromMemory(kVertex, fragment.c_str());
        if (shader.id != 0 && shader.id != rlGetShaderIdDefault())
            return true;
        std::string log;
        if (!compile(GL_FRAGMENT_SHADER, fragment, log))
            error = std::string(name) + ": " + log;
        else
            error = std::string(name) + ": link failed";
        shader = Shader{};
        return false;
    }

    GLuint coefficientTexture(const float (&table)[kPhaseCount][kFilterSize])
    {
        GLuint texture = 0;
        glGenTextures(1, &texture);
        glBindTexture(GL_TEXTURE_2D, texture);
        glTexStorage2D(GL_TEXTURE_2D, 1, GL_RGBA32F, kFilterSize / 4, kPhaseCount);
        glTexSubImage2D(GL_TEXTURE_2D, 0, 0, 0, kFilterSize / 4, kPhaseCount, GL_RGBA, GL_FLOAT, table);
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_NEAREST);
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_NEAREST);
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_CLAMP_TO_EDGE);
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_CLAMP_TO_EDGE);
        glBindTexture(GL_TEXTURE_2D, 0);
        return texture;
    }

    // Draws `input` over the whole target through `shader` (texture unit 0 = input).
    void runPass(const Shader &shader, const Texture2D &input, RenderTexture2D &target)
    {
        BeginTextureMode(target);
        BeginShaderMode(shader);
        DrawTexturePro(input, Rectangle{0.0f, 0.0f, static_cast<float>(input.width), static_cast<float>(input.height)},
                       Rectangle{0.0f, 0.0f, static_cast<float>(target.texture.width), static_cast<float>(target.texture.height)},
                       Vector2{0.0f, 0.0f}, 0.0f, WHITE);
        EndShaderMode();
        EndTextureMode();
    }
}

bool DisplayUpscaler::init(std::string &error)
{
    shutdown();
    if (!loadPass(m_easu, fsrPass("#define FSR_EASU_F 1", kEasuGlue, kEasuMain), "FSR 1 EASU", error) ||
        !loadPass(m_rcas, fsrPass("#define FSR_RCAS_F 1", kRcasGlue, kRcasMain), "FSR 1 RCAS", error) ||
        !loadPass(m_resample, kResample, "resample", error))
    {
        shutdown();
        return false;
    }
    for (int i = 0; i < 4; ++i)
        m_easuCon[i] = glGetUniformLocation(m_easu.id, ("con" + std::to_string(i)).c_str());
    m_rcasCon = glGetUniformLocation(m_rcas.id, "con");
    m_resampleScale = glGetUniformLocation(m_resample.id, "srcScale");
    m_resampleSize = glGetUniformLocation(m_resample.id, "outSize");

    // NIS_Config.h's NISOptimizer: 128 threads on NVIDIA, 256 elsewhere.
    const char *vendor = reinterpret_cast<const char *>(glGetString(GL_VENDOR));
    const bool nvidia = vendor && std::strstr(vendor, "NVIDIA");
    NISOptimizer upscale(true, nvidia ? NISGPUArchitecture::NVIDIA_Generic : NISGPUArchitecture::AMD_Generic);
    NISOptimizer sharpen(false, nvidia ? NISGPUArchitecture::NVIDIA_Generic : NISGPUArchitecture::AMD_Generic);
    m_nisBlockHeightScale = static_cast<int>(upscale.GetOptimalBlockHeight());
    m_nisBlockHeightSharpen = static_cast<int>(sharpen.GetOptimalBlockHeight());
    std::string nisError;
    m_nisScaler = computeProgram(nisSource(true, m_nisBlockHeightScale, static_cast<int>(upscale.GetOptimalThreadGroupSize())), nisError);
    if (m_nisScaler)
        m_nisSharpen = computeProgram(nisSource(false, m_nisBlockHeightSharpen, static_cast<int>(sharpen.GetOptimalThreadGroupSize())), nisError);
    if (!m_nisScaler || !m_nisSharpen)
    {
        error = "NIS: " + nisError;
        shutdown();
        return false;
    }
    m_nisCoefScale = coefficientTexture(coef_scale);
    m_nisCoefUsm = coefficientTexture(coef_usm);
    glGenBuffers(1, &m_nisConfig);
    glBindBuffer(GL_UNIFORM_BUFFER, m_nisConfig);
    glBufferData(GL_UNIFORM_BUFFER, sizeof(NISConfig), nullptr, GL_DYNAMIC_DRAW);
    glBindBuffer(GL_UNIFORM_BUFFER, 0);
    m_ready = true;
    return true;
}

void DisplayUpscaler::shutdown()
{
    for (Shader *shader : {&m_easu, &m_rcas, &m_resample})
    {
        if (shader->id != 0 && shader->id != rlGetShaderIdDefault())
            UnloadShader(*shader);
        *shader = Shader{};
    }
    for (GLuint *program : {&m_nisScaler, &m_nisSharpen})
        if (*program)
            glDeleteProgram(*program), *program = 0;
    for (GLuint *texture : {&m_nisCoefScale, &m_nisCoefUsm, &m_nisOut})
        if (*texture)
            glDeleteTextures(1, texture), *texture = 0;
    if (m_nisConfig)
        glDeleteBuffers(1, &m_nisConfig), m_nisConfig = 0;
    for (RenderTexture2D *target : {&m_a, &m_b})
        if (target->id)
            UnloadRenderTexture(*target), *target = RenderTexture2D{};
    m_nisOutWidth = m_nisOutHeight = 0;
    m_ready = false;
}

bool DisplayUpscaler::ensureTarget(RenderTexture2D &target, int width, int height)
{
    if (target.id && target.texture.width == width && target.texture.height == height)
        return true;
    if (target.id)
        UnloadRenderTexture(target);
    target = LoadRenderTexture(width, height);
    SetTextureFilter(target.texture, TEXTURE_FILTER_POINT);
    SetTextureWrap(target.texture, TEXTURE_WRAP_CLAMP);
    return target.id != 0;
}

bool DisplayUpscaler::ensureImage(unsigned &texture, int &width, int &height, int wantWidth, int wantHeight)
{
    if (texture && width == wantWidth && height == wantHeight)
        return true;
    if (texture)
        glDeleteTextures(1, &texture);
    glGenTextures(1, &texture);
    glBindTexture(GL_TEXTURE_2D, texture);
    glTexStorage2D(GL_TEXTURE_2D, 1, GL_RGBA8, wantWidth, wantHeight);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_LINEAR);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_LINEAR);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_CLAMP_TO_EDGE);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_CLAMP_TO_EDGE);
    glBindTexture(GL_TEXTURE_2D, 0);
    width = wantWidth;
    height = wantHeight;
    return texture != 0;
}

void DisplayUpscaler::resample(const Texture2D &source, int srcWidth, int srcHeight, RenderTexture2D &target)
{
    const float scale[2] = {static_cast<float>(srcWidth) / source.width, static_cast<float>(srcHeight) / source.height};
    const float size[2] = {static_cast<float>(target.texture.width), static_cast<float>(target.texture.height)};
    glProgramUniform2fv(m_resample.id, m_resampleScale, 1, scale);
    glProgramUniform2fv(m_resample.id, m_resampleSize, 1, size);
    runPass(m_resample, source, target);
}

bool DisplayUpscaler::draw(Kind kind, const Texture2D &frame, int srcWidth, int srcHeight, Rectangle dst, float sharpness,
                           const std::vector<Piece> *pieces)
{
    if (!m_ready || frame.id == 0 || srcWidth < 1 || srcHeight < 1)
        return false;
    // Whole window pixels, so the last pass copies 1:1.
    const int x = static_cast<int>(std::lround(dst.x)), y = static_cast<int>(std::lround(dst.y));
    const int width = static_cast<int>(std::lround(dst.width)), height = static_cast<int>(std::lround(dst.height));
    if (width < 1 || height < 1)
        return false;
    const Rectangle target{static_cast<float>(x), static_cast<float>(y), static_cast<float>(width), static_cast<float>(height)};
    // The result (texW x texH) into the window: whole, or the pieces.
    auto show = [&](const Texture2D &result, float texW, float texH) {
        if (!pieces || pieces->empty())
        {
            DrawTexturePro(result, Rectangle{0.0f, 0.0f, texW, texH}, target, Vector2{0.0f, 0.0f}, 0.0f, WHITE);
            return;
        }
        for (const Piece &piece : *pieces)
            DrawTexturePro(result, Rectangle{piece.u0 * texW, 0.0f, (piece.u1 - piece.u0) * texW, texH}, piece.dst, Vector2{0.0f, 0.0f}, 0.0f,
                           WHITE);
    };
    sharpness = std::clamp(sharpness, 0.0f, 1.0f);
    const bool enlarge = width >= srcWidth && height >= srcHeight;
    rlDrawRenderBatchActive();
    // The scalers sample the frame bilinearly and clamped.
    glBindTexture(GL_TEXTURE_2D, frame.id);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_LINEAR);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_LINEAR);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_CLAMP_TO_EDGE);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_CLAMP_TO_EDGE);
    glBindTexture(GL_TEXTURE_2D, 0);

    if (kind == Kind::Fsr1)
    {
        if (!ensureTarget(m_a, width, height) || !ensureTarget(m_b, width, height))
            return false;
        if (enlarge)
        {
            AU1 con0[4], con1[4], con2[4], con3[4];
            FsrEasuCon(con0, con1, con2, con3, static_cast<AF1>(srcWidth), static_cast<AF1>(srcHeight), static_cast<AF1>(frame.width),
                       static_cast<AF1>(frame.height), static_cast<AF1>(width), static_cast<AF1>(height));
            const AU1 *cons[4] = {con0, con1, con2, con3};
            for (int i = 0; i < 4; ++i)
                glProgramUniform4uiv(m_easu.id, m_easuCon[i], 1, cons[i]);
            runPass(m_easu, frame, m_a);
        }
        else
            resample(frame, srcWidth, srcHeight, m_a);
        // RCAS strength in stops (0 = strongest): sharpness 0.7 is AMD's 0.2 default.
        AU1 con[4];
        FsrRcasCon(con, 2.0f * (1.0f - sharpness) * (1.0f - sharpness));
        glProgramUniform4uiv(m_rcas.id, m_rcasCon, 1, con);
        runPass(m_rcas, m_a.texture, m_b);
        show(m_b.texture, static_cast<float>(width), static_cast<float>(height));
        return true;
    }

    // NIS: the scaler enlarges at most 2x per axis; a larger window gets the
    // rest from the final bilinear stretch. Smaller windows: resize, then
    // NIS's sharpening alone.
    NISConfig config{};
    GLuint program = 0, input = frame.id;
    int outWidth = width, outHeight = height, blockHeight = m_nisBlockHeightSharpen;
    if (enlarge)
    {
        outWidth = std::min(width, srcWidth * 2);
        outHeight = std::min(height, srcHeight * 2);
        if (!NVScalerUpdateConfig(config, sharpness, 0, 0, static_cast<uint32_t>(srcWidth), static_cast<uint32_t>(srcHeight),
                                  static_cast<uint32_t>(frame.width), static_cast<uint32_t>(frame.height), 0, 0,
                                  static_cast<uint32_t>(outWidth), static_cast<uint32_t>(outHeight), static_cast<uint32_t>(outWidth),
                                  static_cast<uint32_t>(outHeight)))
            return false;
        program = m_nisScaler;
        blockHeight = m_nisBlockHeightScale;
    }
    else
    {
        if (!ensureTarget(m_a, width, height))
            return false;
        resample(frame, srcWidth, srcHeight, m_a);
        if (!NVSharpenUpdateConfig(config, sharpness, 0, 0, static_cast<uint32_t>(width), static_cast<uint32_t>(height),
                                   static_cast<uint32_t>(width), static_cast<uint32_t>(height), 0, 0))
            return false;
        program = m_nisSharpen;
        input = m_a.texture.id;
    }
    if (!ensureImage(m_nisOut, m_nisOutWidth, m_nisOutHeight, outWidth, outHeight))
        return false;
    rlDrawRenderBatchActive();
    glBindBuffer(GL_UNIFORM_BUFFER, m_nisConfig);
    glBufferSubData(GL_UNIFORM_BUFFER, 0, sizeof(config), &config);
    glBindBuffer(GL_UNIFORM_BUFFER, 0);
    glBindBufferBase(GL_UNIFORM_BUFFER, 0, m_nisConfig);
    glUseProgram(program);
    glActiveTexture(GL_TEXTURE1);
    glBindTexture(GL_TEXTURE_2D, m_nisCoefScale);
    glActiveTexture(GL_TEXTURE2);
    glBindTexture(GL_TEXTURE_2D, m_nisCoefUsm);
    glActiveTexture(GL_TEXTURE0);
    glBindTexture(GL_TEXTURE_2D, input);
    glBindImageTexture(0, m_nisOut, 0, GL_FALSE, 0, GL_WRITE_ONLY, GL_RGBA8);
    glDispatchCompute(static_cast<GLuint>((outWidth + 31) / 32), static_cast<GLuint>((outHeight + blockHeight - 1) / blockHeight), 1);
    glMemoryBarrier(GL_TEXTURE_FETCH_BARRIER_BIT | GL_SHADER_IMAGE_ACCESS_BARRIER_BIT);
    glBindImageTexture(0, 0, 0, GL_FALSE, 0, GL_WRITE_ONLY, GL_RGBA8);
    glActiveTexture(GL_TEXTURE1);
    glBindTexture(GL_TEXTURE_2D, 0);
    glActiveTexture(GL_TEXTURE2);
    glBindTexture(GL_TEXTURE_2D, 0);
    glActiveTexture(GL_TEXTURE0);
    glBindTexture(GL_TEXTURE_2D, 0);
    glUseProgram(0);
    Texture2D out{m_nisOut, outWidth, outHeight, 1, PIXELFORMAT_UNCOMPRESSED_R8G8B8A8};
    SetTextureFilter(out, outWidth == width && outHeight == height ? TEXTURE_FILTER_POINT : TEXTURE_FILTER_BILINEAR);
    show(out, static_cast<float>(outWidth), static_cast<float>(outHeight));
    return true;
}
